with flattened as (select id, customer_id, created_at, k, v from carts lateral view outer explode(attributes) li as k, v), cleaned as (select id, customer_id, created_at, k, quarter(created_at) as created_at_quarter from flattened where created_at >= to_date('2025-03-02')), metrics as (select *, min(created_at_quarter) over w_grp as customer_id_min_created_at_quarter, percent_rank() over (partition by customer_id order by created_at_quarter desc) as created_at_quarter_percent_rank, sum(created_at_quarter) over w_grp as customer_id_sum_created_at_quarter, dense_rank() over (partition by customer_id order by created_at_quarter asc nulls first) as created_at_quarter_dense_rank from cleaned window w_grp as (partition by customer_id)), with_windows as (select *, rank() over (partition by k order by created_at_quarter desc) as created_at_quarter_rank, percent_rank() over (partition by customer_id order by created_at_quarter_percent_rank asc nulls first) as created_at_quarter_percent_rank_percent_rank, avg(customer_id_min_created_at_quarter) over (partition by customer_id order by cast(created_at as bigint) asc range between 7200 preceding and current row) as customer_id_min_created_at_quarter_avg_2h from metrics) select customer_id, created_at, k, created_at_quarter, customer_id_min_created_at_quarter, created_at_quarter_percent_rank, customer_id_sum_created_at_quarter, created_at_quarter_rank, created_at_quarter_percent_rank_percent_rank, case when k rlike '^(weight_kg|gift)$' then 'GROUP_A' else 'PRIORITY' end as k_zone from with_windows order by customer_id_min_created_at_quarter desc nulls last
